<script>
(function () {
    function removeHandler(scope) { scope.querySelectorAll('[data-remove-row]').forEach(function (button) { button.onclick = function () { button.closest('tr').remove(); }; }); }
    function peopleRow(key, row) { return '<tr><td><input name="'+key+'['+row+'][image]" class="form-control"></td><td><input name="'+key+'['+row+'][name]" class="form-control"></td><td><textarea name="'+key+'['+row+'][about]" class="form-control" rows="3"></textarea></td><td><button type="button" class="btn btn-outline-danger" data-remove-row>Remove</button></td></tr>'; }
    document.querySelectorAll('[data-people-table]').forEach(function (table) { removeHandler(table); table.querySelector('[data-add-person]').onclick = function () { var key = table.dataset.peopleTable; table.querySelector('tbody').insertAdjacentHTML('beforeend', peopleRow(key, table.querySelectorAll('tbody tr').length)); removeHandler(table); }; });
    var payment = document.getElementById('payment-table'); if (payment) { removeHandler(payment); payment.querySelector('[data-add-payment]').onclick = function () { var row = payment.querySelectorAll('tbody tr').length; payment.querySelector('tbody').insertAdjacentHTML('beforeend', '<tr><td><input name="payment['+row+'][title]" class="form-control"></td><td><input name="payment['+row+'][amount]" class="form-control"></td><td><input name="payment['+row+'][lateamount]" class="form-control"></td><td><input name="payment['+row+'][currency]" value="INR" class="form-control"></td><td><input name="payment['+row+'][accompany]" class="form-control"></td><td><input name="payment['+row+'][sort]" class="form-control"></td><td><button type="button" class="btn btn-outline-danger" data-remove-row>Remove</button></td></tr>'); removeHandler(payment); }; }
    var session = document.getElementById('session-table'); if (session) { removeHandler(session); session.querySelector('[data-add-session]').onclick = function () { var row = session.querySelectorAll('tbody tr').length; session.querySelector('tbody').insertAdjacentHTML('beforeend', '<tr><td><input name="session['+row+'][title]" class="form-control"></td><td><input name="session['+row+'][sort]" class="form-control"></td><td><button type="button" class="btn btn-outline-danger" data-remove-row>Remove</button></td></tr>'); removeHandler(session); }; }
}());
</script>
@endpush
